import React from "react";
import { useNavigate } from "react-router-dom";

const pinColors = {
  CRITICAL: "bg-red-500",
  HIGH: "bg-orange-500",
  MEDIUM: "bg-amber-400",
  LOW: "bg-green-500",
};

const LiveReportMap = ({ reports }) => {
  const navigate = useNavigate();
  const positions = [
    "left-[32%] top-[43%]",
    "left-[55%] top-[25%]",
    "left-[69%] top-[65%]",
    "left-[73%] top-[78%]",
  ];

  return (
    <section className="rounded-xl border border-gray-100 bg-white p-4 sm:p-5">
      <div className="flex items-start justify-between">
        <div>
          <h2 className="font-['Manrope',sans-serif] text-sm font-bold">
            Incident map
          </h2>
          <p className="mt-1 text-[10px] text-gray-400">
            Live environmental reports across Malawi
          </p>
        </div>
        <button className="rounded-md border border-gray-200 px-2.5 py-1.5 text-[10px] text-gray-600">
          This week⌄
        </button>
      </div>

      <div className="relative mt-4 h-[230px] overflow-hidden rounded-lg bg-[#e8eee5] sm:h-[272px]">
        <div className="absolute inset-0 bg-[linear-gradient(30deg,transparent_49%,#d5e0d3_50%,transparent_51%),linear-gradient(120deg,transparent_48%,#d8e2d7_49%,transparent_50%)] bg-[length:90px_92px,110px_108px]" />
        <div className="absolute -right-10 top-[-15%] h-[130%] w-3 rotate-[25deg] rounded-full bg-[#bedbd7] ring-4 ring-[#dceae4]" />
        <div className="absolute -left-[10%] top-1/2 h-1 w-[120%] -rotate-[19deg] border-y border-[#d9e1d5] bg-white" />
        <div className="absolute -left-[10%] top-[63%] h-0.5 w-[120%] rotate-[22deg] bg-white" />
        <span className="absolute left-[28%] top-[46%] text-[8px] font-bold tracking-widest text-gray-500">LILONGWE</span>
        <span className="absolute left-[52%] top-[17%] text-[8px] font-bold tracking-widest text-gray-500">MZUZU</span>
        <span className="absolute left-[70%] top-[66%] text-[8px] font-bold tracking-widest text-gray-500">ZOMBA</span>
        <span className="absolute left-[75%] top-[81%] text-[8px] font-bold tracking-widest text-gray-500">BLANTYRE</span>

        {reports
          .filter((report) => report.status !== "RESOLVED")
          .map((report, index) => (
            <button
              key={report.id}
              aria-label={`Open ${report.id}`}
              title={`${report.id} · ${report.category}`}
              onClick={() => navigate(`/reports/${report.id}`)}
              className={`absolute z-10 grid h-6 w-6 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border-2 border-white shadow-lg ${
                pinColors[report.severity]
              } ${positions[index % positions.length]}`}
            >
              <span className="h-1.5 w-1.5 rounded-full bg-white" />
            </button>
          ))}

        <span className="absolute bottom-1 right-1 rounded bg-white/80 px-1.5 py-1 text-[7px] text-gray-500">
          Map data © OpenStreetMap contributors
        </span>
        <button
          aria-label="Expand map"
          className="absolute bottom-2 left-2 grid h-7 w-7 place-items-center rounded bg-white text-sm text-gray-600 shadow"
        >
          ⛶
        </button>
      </div>

      <div className="flex flex-wrap items-center gap-3 pt-3 text-[9px] text-gray-500 sm:gap-4">
        {["Critical", "High", "Medium", "Low"].map((level) => (
          <span key={level} className="flex items-center gap-1.5">
            <i className={`h-2 w-2 rounded-full ${pinColors[level.toUpperCase()]}`} />
            {level}
          </span>
        ))}
        <span className="ml-auto text-gray-600">
          {reports.filter((report) => report.status !== "RESOLVED").length} active reports
        </span>
      </div>
    </section>
  );
};

export default LiveReportMap;
